// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CloudResource) predicate.CloudResource {
	return predicate.CloudResource(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CloudResource) predicate.CloudResource {
	return predicate.CloudResource(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CloudResource) predicate.CloudResource {
	return predicate.CloudResource(sql.NotPredicates(p))
}
